quasarPanelData.forEach(data => {
    let categoriesGroups = document.createElement('div');
    categoriesGroups.className='q-category_groups';

    let categoriesTitleGroups = document.createElement('div');
    categoriesTitleGroups.className='q-category_title_groups';
    categoriesTitleGroups.style.borderImage ='url("https://i.pinimg.com/originals/66/a5/89/66a5892c919c794f8d55e99ece6de86b.gif") 1 stretch';

    let categoriesImageGroups = document.createElement('div');
    categoriesImageGroups.className='q-image_groups';
    categoriesImageGroups.innerHTML = data.svg;

    let categoriesTitle = document.createElement('span');
    categoriesTitle.className='q-category_title';
    categoriesTitle.textContent= data.title;

    categoriesTitleGroups.append(categoriesImageGroups,categoriesTitle)

    let ulElement = document.createElement('ul');

    data.elements.forEach(element => {
        let elementLink = document.createElement('button');
        elementLink.setAttribute('onclick', `QuasarScriptorium(${element.link})`);
        // elementLink.href = `/found panel/${element.link}`;
        // elementLink.href = `${location.origin}/found%20panel/${element.link}`;
        elementLink.className='q-type_groups';
        elementLink.addEventListener('click', () => {
            document.querySelectorAll('.q-type_groups').forEach(r => {r.classList.remove('quasar-active')})
            elementLink.classList.add('quasar-active')
        })
        let elementImageGroups = document.createElement('div');
        elementImageGroups.className='q-image_groups';
        elementImageGroups.innerHTML=  element.svg;

        let elementTitle = document.createElement('li');
        elementTitle.className='q-type_title';
        elementTitle.textContent=element.title;

        elementLink.append(elementImageGroups,elementTitle)
        ulElement.appendChild(elementLink);
    })


    categoriesGroups.append(categoriesTitleGroups,ulElement);

    sideBarContainer.appendChild(categoriesGroups)
})